"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { Button as BaseButton } from "@base-ui/react/button";

import { mergeClassName } from "../shared/merge-class-name.js";
import { styles } from "./label.stylex.js";

export type LabelColor = "blue" | "red" | "violet";

export interface LabelProps extends Omit<BaseButton.Props, "children" | "className"> {
  children: React.ReactNode;
  className?: BaseButton.Props["className"];
  color?: LabelColor;
  marker?: React.ReactNode | false;
  open?: boolean;
}

export const Label = React.forwardRef<HTMLElement, LabelProps>(function Label(
  { children, className, color = "red", marker, nativeButton, open = false, render, ...props },
  ref,
) {
  const generated = stylex.props(styles.root, open && styles.open).className;

  return (
    <BaseButton
      {...props}
      aria-expanded={props["aria-expanded"] ?? (open ? true : undefined)}
      className={mergeClassName(generated, className)}
      data-color={color}
      data-open={open ? "true" : undefined}
      data-slot="label"
      nativeButton={nativeButton ?? render === undefined}
      ref={ref}
      render={render}
    >
      {marker !== false && (
        <span
          aria-hidden="true"
          data-slot="label-marker"
          {...stylex.props(styles.marker, marker === undefined && styles[color])}
        >
          {marker}
        </span>
      )}
      <span data-slot="label-text">{children}</span>
    </BaseButton>
  );
});

import * as stylex from "@stylexjs/stylex";

import { tokens } from "../tokens.stylex.js";

export const styles = stylex.create({
  root: {
    alignItems: "center",
    backgroundColor: {
      default: tokens.colorLabelSurfaceDefault,
      ":hover": tokens.colorLabelSurfaceHover,
      ":active": tokens.colorLabelSurfaceHover,
      '[data-visual-state="hover"]': tokens.colorLabelSurfaceHover,
      '[data-visual-state="active"]': tokens.colorLabelSurfaceHover,
    },
    borderRadius: tokens.radiusRounded,
    borderColor: tokens.colorLabelBorder,
    borderStyle: "solid",
    borderWidth: tokens.sizeBorderControl,
    boxSizing: "border-box",
    color: {
      default: tokens.colorLabelContentDefault,
      ":hover": tokens.colorLabelContentHover,
      ":active": tokens.colorLabelContentHover,
      '[data-visual-state="hover"]': tokens.colorLabelContentHover,
      '[data-visual-state="active"]': tokens.colorLabelContentHover,
    },
    cursor: "pointer",
    display: "inline-flex",
    flexShrink: 0,
    fontFamily: tokens.fontSans,
    fontSize: "12px",
    fontWeight: 400,
    gap: tokens.spaceLabelGap,
    height: tokens.sizeLabel,
    justifyContent: "center",
    letterSpacing: 0,
    lineHeight: "14.5px",
    outline: {
      default: "none",
      ":focus-visible": `1px solid ${tokens.colorFocusRing}`,
    },
    outlineOffset: "1px",
    paddingBlock: 0,
    paddingInline: "8px",
    textAlign: "left",
    transitionDuration: "0s",
    whiteSpace: "nowrap",
  },
  open: {
    backgroundColor: tokens.colorLabelSurfaceOpen,
    color: tokens.colorLabelContentHover,
  },
  marker: {
    borderRadius: tokens.radiusRounded,
    display: "inline-flex",
    flexShrink: 0,
    height: tokens.sizeLabelMarker,
    width: tokens.sizeLabelMarker,
  },
  red: {
    backgroundColor: tokens.colorLabelMarkerRed,
  },
  violet: {
    backgroundColor: tokens.colorLabelMarkerPurple,
  },
  blue: {
    backgroundColor: tokens.colorLabelMarkerBlue,
  },
});

export type ClassName<State> = string | ((state: State) => string | undefined);

export function mergeClassName<State>(
  generated?: string,
  className?: ClassName<State>,
): ClassName<State> {
  if (typeof className === "function") {
    return (state) => [generated, className(state)].filter(Boolean).join(" ");
  }
  return [generated, className].filter(Boolean).join(" ");
}
